SELECT e.finalidade, COUNT(*) AS linhas FROM `basedosdados.br_bcb_sicor.operacao` AS o JOIN `basedosdados.br_bcb_sicor.fonte_recurso` AS f ON o.id_fonte_recurso = f.id_fonte_recurso JOIN `basedosdados.br_bcb_sicor.empreendimento` AS e ON o.id_empreendimento = e.id_empreendimento WHERE o.ano_emissao = 2022 AND f.indicador_recurso_publico = '1' GROUP BY e.finalidade ORDER BY linhas DESC